#pragma once

#include "synth.hpp"

#include <cstdint>
#include <map>
#include <string>
#include <vector>

namespace wauvio {
    namespace vocal {

        // Non-lexical vocal events (laughs, giggles, sobs, shouts, hums, interjections).
        // They are written as a lyric tag, e.g. `<laugh>`, `<laugh:he,intensity=0.8>`,
        // `<sob>`, `<hmm?>`, `<kyaa>`, and are expanded at render time into ordinary
        // notes with pitch contours and expression lanes, so they
        // are generated by the same voice, not spelled out as syllables.
        //   <kind[:variant][,intensity=0..1][,pitch=semitones][,key=value...]>
        struct EventSpec {
            std::string kind, variant;
            std::map<std::string, float> p;
            float get(const std::string& k, float d) const { auto it = p.find(k); return it == p.end() ? d : it->second; }
        };

        inline bool is_event_tag(const std::string& s) { return s.size() >= 3 && s.front() == '<' && s.back() == '>'; }

        inline bool parse_event_tag(const std::string& tag, EventSpec& out) {
            if (!is_event_tag(tag)) return false;
            std::string in = tag.substr(1, tag.size() - 2);
            out = EventSpec();
            size_t pos = 0; bool first = true;
            while (pos <= in.size()) {
                size_t c = in.find(',', pos); if (c == std::string::npos) c = in.size();
                std::string part = in.substr(pos, c - pos);
                if (first) {
                    size_t co = part.find(':');
                    out.kind = part.substr(0, co); if (co != std::string::npos) out.variant = part.substr(co + 1);
                    first = false;
                } else {
                    size_t eq = part.find('=');
                    if (eq != std::string::npos) { try { out.p[part.substr(0, eq)] = std::stof(part.substr(eq + 1)); } catch (...) {} }
                }
                pos = c + 1;
            }
            return !out.kind.empty();
        }

        namespace ev_detail {
            struct Rng {
                uint32_t s;
                float next() { s ^= s << 13; s ^= s >> 17; s ^= s << 5; return static_cast<float>(s & 0xFFFFFF) / 16777216.f; }
                float sym() { return next() * 2.f - 1.f; }
            };

            // normalised (0..1) contour -> seconds, offset by the fractional part of the pitch
            inline Curve scale_contour(const std::vector<std::pair<double, double>>& c, double dur, double off) {
                Curve o; for (auto& k : c) o.push_back({ k.first * dur, k.second + off }); return o;
            }

            inline SynthNote make(const SynthNote& par, double t0, double dur, double midi_f, const std::string& lyric, float vel,
                                  const std::vector<std::pair<double, double>>& contour)
            {
                SynthNote n;
                n.start = t0; n.dur = dur; n.midi = static_cast<int>(std::lround(midi_f)); n.vel = std::min(1.f, std::max(0.05f, vel));
                n.style = par.style; n.art = par.art; n.glide_from = -1.0;
                n.style.vibrato_depth = 0.f; n.style.scoop = 0.f; n.style.exit_fall = 0.f; n.style.tremor = par.style.tremor;
                n.style.devoicing = false;
                n.morae = parse_lyric(lyric);
                const double off = midi_f - static_cast<double>(n.midi);
                if (!contour.empty()) n.bend = scale_contour(contour, dur, off);
                else if (off != 0.0) n.bend = { { 0.0, off }, { dur, off } };
                return n;
            }
            inline void glottal_end(SynthNote& n) {           // abrupt stop with a touch of creak (あっ!)
                n.style.release = 0.f;
                n.lanes.push_back({ Ch::Fry, Curve{ { std::max(0.0, n.dur - 0.06), 0.0 }, { std::max(0.001, n.dur - 0.012), 0.7 } } });
            }
            struct Interj { const char* lyric; std::vector<std::pair<double, double>> contour; float vel, breath; bool glottal; float mouth, tension; };
            inline const std::map<std::string, Interj>& interjections() {
                static const std::map<std::string, Interj> m = {
                    { "ah",   { "あ",   { {0, 0}, {.7, 2.2}, {1, 2.0} },            .75f, .10f, true,  .2f, .5f } },
                    { "eh",   { "え",   { {0, 0}, {1, 4.0} },                        .80f, .10f, true,  .2f, .5f } },
                    { "un",   { "うん", { {0, 1.2}, {.55, .6}, {1, -1.0} },          .60f, .10f, false, 0.f, .4f } },
                    { "fuun", { "ふーん", { {0, 1.0}, {.4, -.5}, {1, -2.0} },        .55f, .20f, false, 0.f, .4f } },
                    { "uun",  { "うーん", { {0, 0}, {.5, 1.0}, {1, -1.0} },          .55f, .15f, false, 0.f, .4f } },
                    { "eeto", { "えーと", { {0, 0}, {1, -.5} },                      .60f, .15f, false, .1f, .4f } },
                    { "ano",  { "あのー", { {0, 0}, {.6, 0}, {1, -1.0} },            .60f, .15f, false, .1f, .4f } },
                    { "waa",  { "わあ", { {0, -1.0}, {.4, 3.0}, {1, 1.0} },          .80f, .15f, false, .3f, .45f } },
                    { "hya",  { "ひゃ", { {0, 2.0}, {.3, 5.0}, {1, 3.0} },           .90f, .05f, true,  .1f, .8f } },
                    { "hee",  { "へー", { {0, 0}, {.5, 2.0}, {1, -1.0} },            .65f, .12f, false, .1f, .4f } },
                    { "eee",  { "えー", { {0, 1.0}, {.3, 3.0}, {1, -2.0} },          .75f, .10f, false, .2f, .5f } },
                    { "maa",  { "まあ", { {0, 1.0}, {.5, 2.5}, {1, 0.0} },           .65f, .15f, false, .2f, .4f } } };
                return m;
            }
        }

        inline std::vector<std::string> event_kinds() {
            std::vector<std::string> v = { "laugh", "giggle", "sob", "hum", "hmm", "shout", "kyaa" };
            for (auto& kv : ev_detail::interjections()) v.push_back(kv.first);
            return v;
        }

        // Expands one event note into ordinary notes. Returns an empty list for an unknown kind.
        inline std::vector<SynthNote> expand_event(const SynthNote& par, const EventSpec& sp, uint32_t seed) {
            using namespace ev_detail;
            std::vector<SynthNote> out;
            Rng rng{ seed ? seed : 0x9E3779B9u };
            const float I = clamp01(sp.get("intensity", 0.6f));
            const double t0 = par.start, D = std::max(0.05, par.dur);
            const double base = static_cast<double>(par.midi) + static_cast<double>(sp.get("pitch", 0.f));
            const std::string& k = sp.kind;

            if (k == "laugh" || k == "giggle") {
                const bool gig = (k == "giggle");
                std::vector<std::string> syl;
                const std::string v = sp.variant.empty() ? (gig ? "fu" : "ha") : sp.variant;
                if (v == "kusu") syl = { "くす", "くす" }; else syl = { v };
                const double rate = gig ? 5.5 + 2.5 * I : 4.2 + 3.0 * I;
                const int N = std::max(2, static_cast<int>(std::floor(D * rate)));
                const double period = D / N;
                for (int i = 0; i < N; ++i) {
                    const double ph = N > 1 ? static_cast<double>(i) / (N - 1) : 0.0;
                    const double jit = i ? static_cast<double>(rng.sym()) * 0.07 * period : 0.0;
                    const double bl = period * (gig ? 0.46 : 0.50 + 0.12 * I);
                    const double ts = t0 + i * period + jit;
                    const double pitch = base + (gig ? 0.7 * ph : -(2.5 + 3.0 * I) * ph) + static_cast<double>(rng.sym()) * 0.35;
                    const float vel = (gig ? 0.38f + 0.30f * I : 0.55f + 0.38f * I) * static_cast<float>(1.0 - 0.4 * ph);
                    SynthNote n = make(par, ts, bl, pitch, syl[static_cast<size_t>(i) % syl.size()], vel,
                                       { { 0, 0.8 * I * (gig ? 0.4 : 1.0) }, { 1, -0.9 * I } });
                    Style& s = n.style;
                    s.breathiness = gig ? 0.50f : 0.30f + 0.30f * (1.f - I); s.tension = gig ? 0.30f : 0.45f;
                    s.attack_sharpness = 0.8f; s.release = 0.35f; s.legato = 0.f; s.consonant_strength = 0.85f; s.consonant_duration = 0.8f;
                    s.air = gig ? 0.35f : 0.20f; s.portamento = 0.01f; s.softness = gig ? 0.3f : 0.f;
                    s.formant_shift += gig ? 0.4f : 0.f; s.mouth_open = gig ? -0.1f : 0.25f * I;
                    out.push_back(std::move(n));
                }
            } else if (k == "sob") {
                const int units = std::max(1, static_cast<int>(D / 0.65));
                const double ul = D / units;
                for (int u = 0; u < units; ++u) {
                    const double ts = t0 + u * ul;
                    const double hitch = std::min(0.12, ul * 0.18);
                    // (a short silent catch before each sob unit)
                    const double vs = ts + hitch + 0.01, vl = ul - hitch - 0.015;
                    if (vl < 0.05) continue;
                    const bool crack = (u == 0 && I > 0.4f);
                    SynthNote n = make(par, vs, vl, base - static_cast<double>(u) / units, sp.variant.empty() ? "あ" : sp.variant, 0.5f + 0.3f * I,
                                       crack ? std::vector<std::pair<double, double>>{ {0, 0}, {.30, 0}, {.34, 6.0}, {.45, 2.5}, {1, -1.5} }
                                             : std::vector<std::pair<double, double>>{ {0, 0.8}, {1, -1.5} });
                    Style& s = n.style;
                    s.tremor = 0.55f; s.tremor_rate = 8.f; s.breathiness = 0.35f; s.tension = 0.65f; s.softness = 0.3f; s.formant_shift += 0.3f;
                    if (crack) n.lanes.push_back({ Ch::Register, Curve{ { 0.0, 0.0 }, { 0.30 * vl, 0.0 }, { 0.34 * vl, 0.9 }, { 0.50 * vl, 0.4 }, { vl, 0.0 } } });
                    out.push_back(std::move(n));
                }
            } else if (k == "hum" || k == "hmm") {
                const std::string v = sp.variant.empty() ? "hmm" : sp.variant;
                auto hum = [&](double ts, double d, std::vector<std::pair<double, double>> c, double pitch) {
                    SynthNote n = make(par, ts, d, pitch, "んー", 0.5f + 0.3f * I, c);
                    n.art = audio::Articulation::Humming; n.style.softness = 0.4f; n.style.breathiness = 0.15f;
                    out.push_back(std::move(n));
                };
                if (v == "hm?")       hum(t0, D, { {0, -0.5}, {.6, 0}, {1, 3.0} }, base);
                else if (v == "mhm") { hum(t0, D * 0.45, { {0, 0.5}, {1, -0.8} }, base); hum(t0 + D * 0.53, D * 0.47, { {0, -0.5}, {1, 1.8} }, base); }
                else                  hum(t0, D, { {0, 0.8}, {1, -1.2} }, base);
            } else if (k == "shout" || k == "kyaa") {
                SynthNote n = make(par, t0, D, base, sp.variant.empty() ? "きゃー" : sp.variant, 0.9f + 0.1f * I,
                                   { {0, -1.5}, {0.08, 3.5}, {0.35, 4.5}, {1, 2.0} });
                Style& s = n.style;
                s.power = 0.95f; s.tension = 0.85f; s.brightness = 0.9f; s.volume *= 1.1f; s.glottal_onset = 0.5f; s.growl = 0.10f + 0.15f * I;
                s.consonant_strength = 0.9f; s.attack_sharpness = 0.9f; s.mouth_open = 0.4f;
                out.push_back(std::move(n));
            } else {
                auto it = interjections().find(k);
                if (it != interjections().end()) {
                    const Interj& ij = it->second;
                    SynthNote n = make(par, t0, D, base, sp.variant.empty() ? ij.lyric : sp.variant, ij.vel * (0.7f + 0.5f * I), ij.contour);
                    Style& s = n.style; s.breathiness = std::max(s.breathiness, ij.breath); s.mouth_open = ij.mouth; s.tension = ij.tension;
                    if (ij.glottal) glottal_end(n);
                    out.push_back(std::move(n));
                }
            }
            return out;
        }

    }
}
